class BipartiteGraph {
  List<List<int>> _adjacencyList;
  int leftSize, rightSize;

  BipartiteGraph(this.leftSize, this.rightSize) : 
      _adjacencyList = List.generate(leftSize + rightSize, (_) => <int>[]);


  void addEdge(int u, int v) {
    if (u >= leftSize || v >= rightSize) return;
    _adjacencyList[u].add(v);
  }


  bool isBipartite() {
    final color = List.filled(_adjacencyList.length, -1); 

    for (int i = 0; i < _adjacencyList.length; i++) {
      if (color[i] == -1) {
        Queue<int> queue = Queue();
        queue.add(i);
        color[i] = 0;

        while (queue.isNotEmpty) {
          int node = queue.removeFirst();

          for (int neighbor in _adjacencyList[node]) {
            if (color[neighbor] == -1) {
              color[neighbor] = color[node] ^ 1; 
              queue.add(neighbor);
            } else if (color[neighbor] == color[node]) {
              return false; 
            }
          }
        }
      }
    }

    return true;
  }
}

class BipartiteGraph {
  final Set<int> leftSet;
  final List<List<int>> adjacencyList;

  BipartiteGraph(this.leftSet, this.adjacencyList);

  bool isBipartite() {
    final Map<int, int> colors = {}; // -1: uncolored, 0: color A, 1: color B

    for (final vertex in leftSet) {
      if (!colors.containsKey(vertex)) {
        if (!_bfsColoring(adjacencyList[vertex] ?? [], colors, vertex, 0)) return false;
      }
    }

    return true;
  }

  bool _bfsColoring(List<int> neighbors, Map<int, int> colors, int startVertex, int color) {
    Queue<(int, int)> queue = Queue();
    queue.add((startVertex, color));

    while (queue.isNotEmpty) {
      final (currentVertex, currentColor) = queue.removeFirst();

      if (currentColor == null || colors[currentVertex] != null) continue;

      colors[currentVertex] = currentColor;

      for (final neighbor in neighbors) {
        if (neighbor < 0) continue; 

        final expectedColor = (currentColor + 1) % 2;
        if (colors.containsKey(neighbor) && colors[neighbor]! != expectedColor) {
          print('Conflict detected at vertex $neighbor');
          return false;
        }
        queue.add((neighbor, expectedColor));
      }
    }

    return true;
  }
}

