int modInverseInt(int a, int n) {
  var gcdResult = extendedEuclidean(a % n, n);
  if (gcdResult[0] != 1) throw Exception('No inverse');
  return ((gcdResult[1] % n + n) % n).toInt();
}

List<int> extendedEuclidean(int a, int b) {
  List<List<int>> table = [
    [1, 0],
    [0, 1],
  ];
  while (true) {
    if (b == 0) return table[0];
    var q = a ~/ b;
    var tmp = a - b * q;
    a = b;
    b = tmp;
    table.insert(table.length - 1, table[table.length - 2]);
    table.last.setRange(1, 2, table[table.length - 2].setAll(2));
  }
}

